import{_ as o,o as a,c as r,a3 as t}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Preenchimento automático de CPHA","description":"","frontmatter":{"title":"Preenchimento automático de CPHA","id":"rupe-cpha-preenchimento","plataforma":"RUPE","grupo":"RUPE","plano":"free","desde":"1.2.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/rupe-cpha-preenchimento"}]]},"headers":[],"relativePath":"funcionalidades/rupe-cpha-preenchimento.md","filePath":"funcionalidades/rupe-cpha-preenchimento.md"}'),c={name:"funcionalidades/rupe-cpha-preenchimento.md"};function s(i,e,d,n,l,p){return a(),r("div",null,e[0]||(e[0]=[t('<h1 id="preenchimento-automatico-de-cpha" tabindex="-1">Preenchimento automático de CPHA <a class="header-anchor" href="#preenchimento-automatico-de-cpha" aria-label="Permalink to &quot;Preenchimento automático de CPHA&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>No cadastro de CPHA do RUPE, preenche o formulário a partir de um texto com os dados do advogado (nome, CPF, OAB, e-mail, NIT, banco, agência, conta e outros), copiado do processo. Um painel mostra o que foi reconhecido, para você conferir e corrigir. O eploc aprende com as correções para as próximas vezes.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>RUPE</strong> (<code>rupe.tjmg.jus.br</code>), formulário de cadastro de CPHA. Os rótulos aprendidos ficam nas configurações do eploc, no card do recurso (&quot;Gerenciar rótulos aprendidos&quot;).</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>No processo, copie de uma vez o trecho com os dados informados pelo advogado.</li><li>Volte ao cadastro de CPHA e cole (Ctrl+V) em qualquer campo do formulário, ou clique em <strong>Preencher com dados copiados</strong>.</li><li>Os campos reconhecidos são preenchidos, e o painel &quot;Dados detectados&quot; mostra o texto colado com cada dado reconhecido destacado como uma etiqueta. Passe o mouse sobre uma etiqueta para ver em que campo ela entrou.</li><li>Para corrigir, clique numa etiqueta ou selecione um trecho do texto e escolha, no menu &quot;Este dado é…&quot;, o campo certo. Para desfazer o reconhecimento de um trecho, use &quot;Desfazer — volta a ser texto simples&quot;.</li><li>Quando você indica o campo de um dado, o eploc aprende o rótulo que vinha antes dele no texto (por exemplo, &quot;Nº OAB&quot;) e, nas próximas colagens, leva o dado direto para esse campo.</li><li>Confira o formulário e salve como de costume. O painel fecha sozinho quando o cadastro é fechado.</li></ol><p>Os campos de seleção do formulário (banco, juiz etc.) também ganham busca por digitação.</p><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Lembrar o último juiz selecionado e pré-selecioná-lo automaticamente</td><td>ligada</td><td>O juiz escolhido no último cadastro já vem selecionado.</td></tr></tbody></table><p>No card, <strong>Gerenciar rótulos aprendidos</strong> lista os rótulos que o eploc aprendeu e permite apagá-los.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O reconhecimento depende de como o advogado escreveu os dados. Sempre confira o formulário antes de salvar.</li><li>O botão <strong>Preencher com dados copiados</strong> lê a área de transferência. Se o navegador não permitir essa leitura, o eploc avisa: nesse caso, cole o texto (Ctrl+V) em qualquer campo do formulário.</li></ul>',13)]))}const h=o(c,[["render",s]]);export{m as __pageData,h as default};
